return ['domain'=>NULL,'plural-forms'=>'nplurals=3; plural=(n == 1) ? 0 : ((n % 10 >= 2 && n % 10 <= 4 && (n % 100 < 12 || n % 100 > 14)) ? 1 : 2);','language'=>'pl_PL','project-id-version'=>'Babilim 1.2.2','pot-creation-date'=>'2026-11-09T07:54:32+00:00','po-revision-date'=>'2026-11-09T07:54:32+00:00','x-generator'=>'Babilim','messages'=>['Sent when you press Enable Babilim, and again if the site has to register anew: your site\'s URL, the WordPress, PHP and Babilim versions, the language of your site and the languages in use on it, and a public key generated for this site.'=>'Wysyłane po kliknięciu Włącz Babilim oraz ponownie, jeśli witryna musi zarejestrować się od nowa: adres URL witryny, wersje WordPress, PHP i Babilim, język witryny oraz używane w niej języki, a także klucz publiczny wygenerowany dla tej witryny.','Sent on every check: the list of installed plugins and themes with the state of any Babilim translation installed for them, the languages in use, and short diagnostic codes.'=>'Wysyłane przy każdym sprawdzeniu: lista zainstalowanych wtyczek i motywów wraz ze stanem wszystkich zainstalowanych dla nich tłumaczeń Babilim, używane języki oraz krótkie kody diagnostyczne.','Every request includes your site\'s URL, and the site\'s access token is included whenever the service needs it.'=>'Każde żądanie zawiera adres URL witryny, a token dostępu witryny jest dołączany zawsze, gdy usługa go potrzebuje.','What Babilim sends to the service'=>'Co Babilim wysyła do usługi','Your site\'s URL'=>'Adres URL Twojej witryny','WordPress version'=>'Wersja WordPress','PHP version'=>'Wersja PHP','Babilim version'=>'Wersja Babilim','Your site\'s language'=>'Język Twojej witryny','Languages in use on your site'=>'Używane języki w Twojej witrynie','A public key for this site'=>'Klucz publiczny tej witryny','A public key generated for this site, used to prove requests genuinely come from this site. Only the public half is ever sent; the private half stays on your site.'=>'Klucz publiczny wygenerowany dla tej witryny, służący do potwierdzenia, że żądania faktycznie pochodzą z tej witryny. Wysyłana jest wyłącznie część publiczna; część prywatna pozostaje w Twojej witrynie.','Installed plugins and themes'=>'Zainstalowane wtyczki i motywy','For every installed plugin and theme: its name (slug), version, text domain, whether it is listed on WordPress.org, and the languages it already includes. For each Babilim translation you have installed: which version it is, when it was last checked, and whether it passed its file check.'=>'Dla każdej zainstalowanej wtyczki i każdego motywu: nazwa (slug), wersja, text domain, informacja, czy znajduje się w WordPress.org, oraz języki, które już zawiera. Dla każdego zainstalowanego tłumaczenia Babilim: jego wersja, czas ostatniego sprawdzenia i informacja, czy przeszło sprawdzanie pliku.','Source files (only if you confirm an upload)'=>'Pliki źródłowe (tylko jeśli potwierdzisz przesłanie)','Diagnostic codes'=>'Kody diagnostyczne','Up to 20 short diagnostic codes (for example, a translation file that failed its check), each with the plugin or theme, the language and the time it happened. They never contain any text from your site or any translated text.'=>'Do 20 krótkich kodów diagnostycznych (na przykład plik tłumaczenia, który nie przeszedł sprawdzenia), każdy z informacją o wtyczce lub motywie, języku i czasie zdarzenia. Nigdy nie zawierają żadnego tekstu z Twojej witryny ani przetłumaczonego tekstu.','%1$d site on this network is set to erase its Babilim identity when the plugin is deleted. The paid license attached to that site could then not be restored automatically; you would have to contact Babilim support at %2$s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in that site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'%1$d witryna w tej sieci jest ustawiona tak, aby usunąć tożsamość Babilim po usunięciu wtyczki. Licencja płatna przypisana do tej witryny nie mogłaby wtedy zostać przywrócona automatycznie; musiałbyś skontaktować się ze wsparciem Babilim pod adresem %2$s. Aby zachować tożsamość, naciśnij Anuluj, odznacz „Usuń wszystkie dane Babilim podczas odinstalowania” w ustawieniach Babilim tej witryny i ponownie dezaktywuj. Dezaktywować mimo to?' . "\0" . '%1$d witryny w tej sieci są ustawione tak, aby usunąć tożsamość Babilim po usunięciu wtyczki. Licencja płatna przypisana do tych witryn nie mogłaby wtedy zostać przywrócona automatycznie; musiałbyś skontaktować się ze wsparciem Babilim pod adresem %2$s. Aby zachować tożsamości, naciśnij Anuluj, odznacz „Usuń wszystkie dane Babilim podczas odinstalowania” w ustawieniach Babilim każdej witryny i ponownie dezaktywuj. Dezaktywować mimo to?' . "\0" . '%1$d witryn w tej sieci jest ustawionych tak, aby usunąć tożsamość Babilim po usunięciu wtyczki. Licencja płatna przypisana do tych witryn nie mogłaby wtedy zostać przywrócona automatycznie; musiałbyś skontaktować się ze wsparciem Babilim pod adresem %2$s. Aby zachować tożsamości, naciśnij Anuluj, odznacz „Usuń wszystkie dane Babilim podczas odinstalowania” w ustawieniach Babilim każdej witryny i ponownie dezaktywuj. Dezaktywować mimo to?','%1$s %2$s.'=>'%1$s %2$s.','%1$s (%2$s): %3$s'=>'%1$s (%2$s): %3$s','%1$s nothing to do.'=>'%1$s nic do zrobienia.','%1$s: %2$s'=>'%1$s: %2$s','%1$s: %2$s (%3$s)'=>'%1$s: %2$s (%3$s)','%1$s: %2$s. Choose the language.'=>'%1$s: %2$s. Wybierz język.','%d failed'=>'Niepowodzenie: %d' . "\0" . 'Niepowodzenie: %d' . "\0" . 'Niepowodzenie: %d','%d not yet tried'=>'Jeszcze nie próbowano: %d' . "\0" . 'Jeszcze nie próbowano: %d' . "\0" . 'Jeszcze nie próbowano: %d','%d report is waiting. "Always share" and "Don\'t share" apply to all of them.'=>'%d raport czeka. Opcje „Zawsze udostępniaj” i „Nie udostępniaj” dotyczą wszystkich.' . "\0" . '%d raporty czekają. Opcje „Zawsze udostępniaj” i „Nie udostępniaj” dotyczą wszystkich.' . "\0" . '%d raportów czeka. Opcje „Zawsze udostępniaj” i „Nie udostępniaj” dotyczą wszystkich.','%d skipped'=>'Pominięto: %d' . "\0" . 'Pominięto: %d' . "\0" . 'Pominięto: %d','%d succeeded'=>'Powodzenie: %d' . "\0" . 'Powodzenie: %d' . "\0" . 'Powodzenie: %d','%d to install'=>'%d do zainstalowania' . "\0" . '%d do zainstalowania' . "\0" . '%d do zainstalowania','(a public key generated for this site)'=>'(klucz publiczny wygenerowany dla tej witryny)','(detected)'=>'(wykryto)','(generic codes and coordinates only)'=>'(wyłącznie ogólne kody i współrzędne)','A cleanup was paused on %1$s: %2$s. Nothing was deleted.'=>'Czyszczenie zostało wstrzymane %1$s: %2$s. Nic nie zostało usunięte.','A file in the component could not be read, so it was not packaged.'=>'Nie można odczytać pliku w komponencie, więc nie został on spakowany.','A host that serves only one PHP request at a time cannot complete this step.'=>'Hosting obsługujący tylko jedno żądanie PHP naraz nie może ukończyć tego kroku.','A part of the upload kept failing, so the upload was cancelled.'=>'Jedna część przesyłania wciąż kończyła się niepowodzeniem, więc przesyłanie zostało anulowane.','A translation cannot be requested for that locale on this site right now.'=>'Tłumaczenie dla tego locale nie może być teraz zażądane w tej witrynie.','A translation-index write conflicted with another request on %1$s (%2$s) and was not applied; the most recent version was kept.'=>'Zapis indeksu tłumaczeń kolidował z innym żądaniem w %1$s (%2$s) i nie został zastosowany; zachowano najnowszą wersję.','A translation-index write on %1$s (%2$s) could not be completed and was not applied (%3$s).'=>'Zapis indeksu tłumaczeń w %1$s (%2$s) nie mógł zostać ukończony i nie został zastosowany (%3$s).','Account'=>'Konto','Add another language'=>'Dodaj kolejny język','Advanced'=>'Zaawansowane','All'=>'Wszystkie','All free-plan slots for this site are used'=>'Wszystkie miejsca w planie darmowym dla tej witryny są wykorzystane','All languages'=>'Wszystkie języki','Already in WordPress core'=>'Już w rdzeniu WordPress','Already installed.'=>'Już zainstalowano.','Always share'=>'Zawsze udostępniaj','Another installation is running; try again in a moment.'=>'Trwa inna instalacja; spróbuj ponownie za chwilę.','Automatic installs'=>'Automatyczne instalacje','Automatic installs are now off; turn them on again in the settings if you want them.'=>'Automatyczne instalacje są teraz wyłączone; w razie potrzeby włącz je ponownie w ustawieniach.','Available'=>'Dostępne','Available translations can be installed with one click, and missing ones can be requested. While automatic installs are on, translations the service lists as available for the languages you manage are installed during the twice-daily sync.'=>'Dostępne tłumaczenia można zainstalować jednym kliknięciem, a brakujące można zgłosić prośbą. Gdy automatyczne instalacje są włączone, tłumaczenia, które usługa wskazuje jako dostępne dla zarządzanych przez Ciebie języków, są instalowane podczas synchronizacji dwa razy dziennie.','Available · %s'=>'Dostępne · %s','Babilim'=>'Babilim','Babilim Settings'=>'Ustawienia Babilim','Babilim adds translations for every language checked here.'=>'Babilim dodaje tłumaczenia dla każdego zaznaczonego tutaj języka.','Babilim could not confirm a temporary folder outside the website, so the component was not packaged and nothing was uploaded. Define BABILIM_TEMP_DIR in wp-config.php as a writable folder outside the web root (for example a folder next to, not inside, your site\'s public directory), or ask your host for one.'=>'Babilim nie mógł potwierdzić folderu tymczasowego poza witryną, więc komponent nie został spakowany i nic nie zostało przesłane. Zdefiniuj BABILIM_TEMP_DIR w wp-config.php jako folder z możliwością zapisu poza katalogiem głównym witryny (na przykład folder obok publicznego katalogu witryny, a nie wewnątrz niego) lub poproś o niego hosting.','Babilim could not finish checking this site.'=>'Babilim nie mógł dokończyć sprawdzania tej witryny.','Babilim could not finish enabling (%1$s): %2$s'=>'Babilim nie mógł dokończyć włączania (%1$s): %2$s','Babilim could not finish verifying this site (the service could not reach it back). Registration is paused.'=>'Babilim nie mógł dokończyć weryfikacji tej witryny (usługa nie mogła się z nią połączyć zwrotnie). Rejestracja jest wstrzymana.','Babilim could not verify this site, so nothing is downloaded or installed until verification succeeds.'=>'Babilim nie mógł zweryfikować tej witryny, więc nic nie zostanie pobrane ani zainstalowane, dopóki weryfikacja się nie powiedzie.','Babilim could not verify this site, so nothing is downloaded or installed.'=>'Babilim nie mógł zweryfikować tej witryny, więc nic nie zostanie pobrane ani zainstalowane.','Babilim gets translations from the Babilim service for the plugins and themes on this site that have none for your language, and installs the ones your service plan covers.'=>'Babilim pobiera z usługi Babilim tłumaczenia wtyczek i motywów w tej witrynie, które nie mają ich dla Twojego języka, i instaluje te, które obejmuje Twój plan usługi.','Babilim has not been enabled for this site yet.'=>'Babilim nie został jeszcze włączony dla tej witryny.','Babilim has not installed any translation for this language.'=>'Babilim nie zainstalował żadnego tłumaczenia dla tego języka.','Babilim hit an error. Share an error report?'=>'W Babilim wystąpił błąd. Udostępnić raport o błędzie?','Babilim installed %d translation automatically since your last visit.'=>'Babilim zainstalował automatycznie %d tłumaczenie od Twojej ostatniej wizyty.' . "\0" . 'Babilim zainstalował automatycznie %d tłumaczenia od Twojej ostatniej wizyty.' . "\0" . 'Babilim zainstalował automatycznie %d tłumaczeń od Twojej ostatniej wizyty.','Babilim is disabled. Nothing more is sent; translations already installed keep working.'=>'Babilim jest wyłączony. Nic więcej nie jest wysyłane; już zainstalowane tłumaczenia nadal działają.','Babilim is enabled: this site is verified and %d component was found.'=>'Babilim jest włączony: ta witryna jest zweryfikowana i znaleziono %d komponent.' . "\0" . 'Babilim jest włączony: ta witryna jest zweryfikowana i znaleziono %d komponenty.' . "\0" . 'Babilim jest włączony: ta witryna jest zweryfikowana i znaleziono %d komponentów.','Babilim is enabling and checking this site… (last attempt: %s)'=>'Babilim włącza i sprawdza tę witrynę… (ostatnia próba: %s)','Babilim is enabling and checking this site… Reload this page or wait for the scheduled check to finish.'=>'Babilim włącza i sprawdza tę witrynę… Odśwież stronę lub poczekaj na zakończenie zaplanowanego sprawdzenia.','Babilim is not enabled.'=>'Babilim nie jest włączony.','Babilim is set to erase this site\'s identity when the plugin is deleted. The paid license attached to this site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in the Babilim settings, and deactivate again. Deactivate anyway?'=>'Babilim jest ustawiony tak, aby usunąć tożsamość tej witryny po usunięciu wtyczki. Licencja płatna przypisana do tej witryny nie mogłaby wtedy zostać przywrócona automatycznie; musiałbyś skontaktować się ze wsparciem Babilim pod adresem %s. Aby zachować tożsamość, naciśnij Anuluj, odznacz „Usuń wszystkie dane Babilim podczas odinstalowania” w ustawieniach Babilim i ponownie dezaktywuj. Dezaktywować mimo to?','Babilim ran out of time for this step and will continue on the next check.'=>'Babilim nie zdążył zakończyć tego kroku i będzie kontynuował przy następnym sprawdzeniu.','Babilim settings'=>'Ustawienia Babilim','Babilim sync is temporarily delayed by the service (rate limited); it will try again after %s.'=>'Synchronizacja Babilim jest tymczasowo opóźniona przez usługę (limit żądań); spróbuje ponownie po %s.','Babilim was updated while this upload was waiting. The old package was discarded; please confirm the upload again.'=>'Babilim został zaktualizowany w trakcie oczekiwania na to przesłanie. Stary pakiet został odrzucony; potwierdź przesłanie ponownie.','Babilim will upload these files from %1$s (version %2$s): every .php and .js file, every block.json file, and the readme.txt, readme.md, style.css and theme.json in its main folder. They are used to find the text that needs translating and to identify the plugin or theme.'=>'Babilim prześle te pliki z %1$s (wersja %2$s): każdy plik .php i .js, każdy plik block.json oraz readme.txt, readme.md, style.css i theme.json w jego głównym folderze. Służą do znajdowania tekstu wymagającego tłumaczenia oraz do identyfikacji wtyczki lub motywu.','Babilim_Manifest is unavailable: %s'=>'Babilim_Manifest jest niedostępny: %s','Back'=>'Wstecz','Bought a license for this domain before? Enter the restore code you received at checkout.'=>'Kupiono wcześniej licencję dla tej domeny? Wpisz kod przywracania otrzymany podczas składania zamówienia.','Broken placeholder'=>'Uszkodzony symbol zastępczy','Build'=>'Kompilacja','Built'=>'Zbudowano','Bulk actions apply only to the selected language of each selected component.'=>'Akcje zbiorcze dotyczą tylko wybranego języka każdego wybranego komponentu.','Bulk actions apply to every matching language of each selected component.'=>'Akcje zbiorcze dotyczą każdego pasującego języka każdego wybranego komponentu.','Bulk download:'=>'Pobieranie zbiorcze:','Bulk request:'=>'Żądanie zbiorcze:','Bulk update:'=>'Aktualizacja zbiorcza:','Bundled with the plugin'=>'Dołączone do wtyczki','Bundled with the theme'=>'Dołączone do motywu','By clicking Enable, you agree to send the information listed above to Babilim.'=>'Klikając Włącz, zgadzasz się na wysłanie powyższych informacji do Babilim.','By continuing you confirm that you have the right to upload this component.'=>'Kontynuując, potwierdzasz, że masz prawo przesłać ten komponent.','Cancel'=>'Anuluj','Category'=>'Kategoria','Check again'=>'Sprawdź ponownie','Check again now'=>'Sprawdź ponownie teraz','Checkout is not available for this site right now.'=>'Zamówienie nie jest teraz dostępne dla tej witryny.','Choose'=>'Wybierz','Choose a category…'=>'Wybierz kategorię…','Choose a language'=>'Wybierz język','Choose a language…'=>'Wybierz język…','Clear filters'=>'Wyczyść filtry','Close'=>'Zamknij','Component'=>'Komponent','Confirm'=>'Potwierdź','Conflicting keys'=>'Konfliktowe klucze','Continue'=>'Kontynuuj','Continue next batch (%d left)'=>'Kontynuuj następną partię (pozostało: %d)','Continuing…'=>'Kontynuowanie…','Could not back up %s before replacing it.'=>'Nie udało się utworzyć kopii zapasowej pliku %s przed jego zastąpieniem.','Could not create the package archive.'=>'Nie udało się utworzyć archiwum pakietu.','Could not determine active components; the existing merged index was left unchanged.'=>'Nie udało się ustalić aktywnych komponentów; istniejący scalony indeks pozostawiono bez zmian.','Could not determine installed plugins/themes; sweep skipped, nothing was deleted.'=>'Nie udało się ustalić zainstalowanych wtyczek/motywów; pominięto czyszczenie, nic nie zostało usunięte.','Could not load the full WordPress.org locale list from the service, so no other language can be added right now.'=>'Nie udało się wczytać z usługi pełnej listy locale z WordPress.org, więc obecnie nie można dodać innego języka.','Could not move %s into place.'=>'Nie udało się przenieść pliku %s na miejsce.','Could not move the merged index for \'%s\' into place; the previous served index (if any) was removed rather than left half-updated. No default-domain supplement is served for this locale until the next successful rebuild.'=>'Nie udało się umieścić scalonego indeksu dla „%s” na miejscu; poprzedni udostępniany indeks (jeśli istniał) został usunięty, zamiast pozostawić go częściowo zaktualizowanego. Uzupełnienie domyślnej domeny nie będzie udostępniane dla tego locale aż do następnej udanej przebudowy.','Could not open zip: %s'=>'Nie udało się otworzyć pliku zip: %s','Could not prepare %s for rollback.'=>'Nie można przygotować %s do przywrócenia poprzedniej wersji.','Could not read %s back after moving it into place.'=>'Nie można ponownie odczytać %s po przeniesieniu go na miejsce.','Could not read: %s'=>'Nie można odczytać: %s','Could not restore the purchase: %s'=>'Nie udało się przywrócić zakupu: %s','Could not show a new restore code: %s'=>'Nie udało się pokazać nowego kodu przywracania: %s','Could not stage %s'=>'Nie udało się przygotować pliku %s','Could not stage default/%s'=>'Nie udało się przygotować pliku default/%s','Could not start checkout: %s'=>'Nie udało się rozpocząć zamówienia: %s','Could not verify entry count for %s'=>'Nie udało się zweryfikować liczby wpisów dla %s','Could not write the downloaded package to disk.'=>'Nie udało się zapisać pobranego pakietu na dysku.','Could not write the staged merged index.'=>'Nie udało się zapisać przygotowanego scalonego indeksu.','Current translation'=>'Aktualne tłumaczenie','Custom overrides'=>'Własne nadpisania','Danger zone'=>'Strefa zagrożenia','Default supplement entry count mismatch.'=>'Niezgodna liczba wpisów uzupełnienia domyślnego.','Delete all Babilim data on uninstall'=>'Usuń wszystkie dane Babilim podczas odinstalowania','Disable Babilim'=>'Wyłącz Babilim','Disable Babilim? Installed translations are kept, but no further checks or downloads will run.'=>'Wyłączyć Babilim? Zainstalowane tłumaczenia zostaną zachowane, ale kolejne kontrole i pobierania nie będą wykonywane.','Don\'t share'=>'Nie udostępniaj','Download'=>'Pobierz','Downloaded and installed.'=>'Pobrano i zainstalowano.','Downloading…'=>'Pobieranie…','Downloads: %1$d/%2$d (%3$s)'=>'Pobrania: %1$d/%2$d (%3$s)','Each component\'s own contribution to each locale\'s shared default-domain supplement.'=>'Wkład każdego komponentu w uzupełnienie domyślnej domeny wspólne dla danego locale.','Enable Babilim'=>'Włącz Babilim','Enabling…'=>'Włączanie…','English (United States)'=>'angielski (Stany Zjednoczone)','Entries'=>'Wpisy','Entry count mismatch for %s'=>'Niezgodna liczba wpisów dla %s','Error reports'=>'Raporty o błędach','Every locale in use on this site (site locale, installed language packs, user locales, and any you add manually). No locale is treated differently from another.'=>'Każdy locale używany w tej witrynie (locale witryny, zainstalowane pakiety językowe, locale użytkowników oraz te dodane ręcznie). Żaden locale nie jest traktowany inaczej niż pozostałe.','Excluded'=>'Wykluczono','Files with other names or extensions are not included, nor are the uploads, cache, logs, backup, data, vendor, node_modules and languages folders, hidden files, or files whose names match common secrets (wp-config*, .env*, *.sql, *.log, *.pem, *.key). Code files can still contain text or data you would not want to share; check them if you are unsure. The service removes the same kinds of files again on arrival.'=>'Pliki o innych nazwach lub rozszerzeniach nie są uwzględniane, podobnie jak foldery uploads, cache, logs, backup, data, vendor, node_modules i languages, pliki ukryte ani pliki, których nazwy pasują do typowych danych poufnych (wp-config*, .env*, *.sql, *.log, *.pem, *.key). Pliki z kodem nadal mogą zawierać tekst lub dane, których nie chcesz udostępniać; sprawdź je, jeśli masz wątpliwości. Usługa po otrzymaniu ponownie usuwa te same rodzaje plików.','Fills in missing translations for the plugins and themes already installed on your site.'=>'Uzupełnia brakujące tłumaczenia wtyczek i motywów już zainstalowanych w Twojej witrynie.','Free'=>'Bezpłatna','Free-plan slots'=>'Miejsca w planie darmowym','General'=>'Ogólne','If this is on, uninstalling also erases this site\'s identity. The paid license attached to this site cannot be restored automatically afterwards; you would have to contact Babilim support at %s to get it back.'=>'Jeśli ta opcja jest włączona, odinstalowanie usunie także tożsamość tej witryny. Licencji płatnej przypisanej do tej witryny nie będzie można potem automatycznie przywrócić; aby ją odzyskać, musisz skontaktować się ze wsparciem Babilim pod adresem %s.','Included'=>'Uwzględnione','Included in index'=>'Uwzględniono w indeksie','Install available translations automatically'=>'Instaluj dostępne tłumaczenia automatycznie','Installed'=>'Zainstalowano','Installed translations are kept, but no further checks or downloads will run.'=>'Zainstalowane tłumaczenia zostaną zachowane, ale kolejne kontrole i pobierania nie będą wykonywane.','Installed · %s'=>'Zainstalowano · %s','Installed · built for %1$s, this site has %2$s'=>'Zainstalowano · utworzone dla wersji %1$s, ta witryna ma wersję %2$s','Installed · built for %s'=>'Zainstalowano · utworzone dla wersji %s','Installed · built for %s, new version failed'=>'Zainstalowano · przygotowane dla wersji %s, przygotowanie nowej wersji nie powiodło się','Installed · built for %s, new version scheduled'=>'Zainstalowano · utworzone dla wersji %s, nowa wersja jest zaplanowana','Installed · built for %s, translating the new version…'=>'Zainstalowano · utworzone dla wersji %s, trwa tłumaczenie nowej wersji…','Installed · built for %s; this plugin or theme is no longer covered by the site\'s service plan'=>'Zainstalowano · zbudowano dla %s; ta wtyczka lub ten motyw nie jest już objęty planem usługi witryny','Installed · built for a different version'=>'Zainstalowano · utworzone dla innej wersji','Installed · built for a different version, new version failed'=>'Zainstalowano · przygotowane dla innej wersji, przygotowanie nowej wersji nie powiodło się','Installed · built for a different version, new version scheduled'=>'Zainstalowano · utworzone dla innej wersji, nowa wersja jest zaplanowana','Installed · built for a different version, translating the new version…'=>'Zainstalowano · utworzone dla innej wersji, trwa tłumaczenie nowej wersji…','Installed · built for a different version; this plugin or theme is no longer covered by the site\'s service plan'=>'Zainstalowano · zbudowano dla innej wersji; ta wtyczka lub ten motyw nie jest już objęty planem usługi witryny','It is stored by the service\'s hosting provider and processed by AI models to produce the translation.'=>'Są przechowywane przez dostawcę hostingu usługi i przetwarzane przez modele AI w celu przygotowania tłumaczenia.','Keep my own translation overrides when purging everything or uninstalling this plugin.'=>'Zachowaj moje własne nadpisania tłumaczeń przy czyszczeniu wszystkiego lub odinstalowaniu tej wtyczki.','Language'=>'Język','Language:'=>'Język:','Languages'=>'Języki','Languages found on this site: %s.'=>'Języki znalezione na tej witrynie: %s.','Last cleanup on %1$s: %2$d newly marked, %3$d file(s) deleted, %4$d record(s) removed.'=>'Ostatnie czyszczenie: %1$s: nowo oznaczono %2$d, usunięto plików: %3$d, usunięto rekordów: %4$d.','Maintenance'=>'Konserwacja','Maintenance status is not available right now.'=>'Stan konserwacji jest obecnie niedostępny.','Manifest unavailable: %s'=>'Manifest niedostępny: %s','Negation reversed'=>'Odwrócona negacja','No'=>'Nie','No build is available to download for this locale.'=>'Brak wersji do pobrania dla tego locale.','No cleanup has run yet.'=>'Nie przeprowadzono jeszcze żadnego czyszczenia.','No components match these filters. %s'=>'Żaden komponent nie pasuje do tych filtrów. %s','No components synced yet.'=>'Nie zsynchronizowano jeszcze żadnych komponentów.','No installed translation matches.'=>'Żadne zainstalowane tłumaczenie nie pasuje.','No language is managed yet.'=>'Żaden język nie jest jeszcze zarządzany.','No pending challenge for this nonce.'=>'Brak oczekującego wyzwania dla tego nonce.','No pending challenge to verify.'=>'Brak oczekującego wyzwania do zweryfikowania.','No plugins or themes found.'=>'Nie znaleziono wtyczek ani motywów.','No previous build to roll back to.'=>'Brak poprzedniej kompilacji, którą można przywrócić.','No record for %s'=>'Brak rekordu dla %s','No site id is on file to rotate a token for.'=>'Nie zapisano żadnego identyfikatora witryny, dla którego można by zmienić token.','No — component inactive'=>'Nie — komponent nieaktywny','No — component removed'=>'Nie — komponent usunięty','No — installed version differs from the active one'=>'Nie — zainstalowana wersja różni się od aktywnej','Not a valid server_build_id: %s'=>'Nieprawidłowy server_build_id: %s','Not covered by the free service plan'=>'Nieobjęte darmowym planem usługi','Not installed'=>'Nie zainstalowano','Not registered yet'=>'Jeszcze nie zarejestrowano','Not supported'=>'Nieobsługiwane','Not verified'=>'Niezweryfikowano','Note (optional)'=>'Uwaga (opcjonalnie)','Nothing to choose.'=>'Nie ma nic do wyboru.','Nothing to confirm.'=>'Nie ma nic do potwierdzenia.','Off by default: deleting the plugin keeps this site\'s identity, so a reinstall can reuse it.'=>'Domyślnie wyłączone: usunięcie wtyczki zachowuje tożsamość tej witryny, dzięki czemu ponowna instalacja może jej użyć.','One or more served files no longer match the manifest.'=>'Co najmniej jeden z udostępnionych plików nie zgadza się już z manifestem.','One-time purchase for this site: %1$s %2$s. Includes all future translation updates. Payment is handled by Paddle in a new tab.'=>'Jednorazowy zakup dla tej witryny: %1$s %2$s. Obejmuje wszystkie przyszłe aktualizacje tłumaczeń. Płatność jest obsługiwana przez Paddle w nowej karcie.','Only a network administrator can do this, because it changes translation files shared by every site on this network.'=>'Tylko administrator sieci może to zrobić, ponieważ zmienia to pliki tłumaczeń współdzielone przez każdą witrynę w tej sieci.','Only plugins and themes can be packaged.'=>'Pakować można tylko wtyczki i motywy.','Only when you confirm an upload for a plugin or theme that is not on WordPress.org: every .php and .js file, every block.json file, and the readme.txt, readme.md, style.css and theme.json in that component\'s main folder, as a zip, after files that match common secrets are left out.'=>'Tylko po potwierdzeniu przesłania wtyczki lub motywu spoza WordPress.org: każdy plik .php i .js, każdy plik block.json oraz readme.txt, readme.md, style.css i theme.json w głównym folderze tego komponentu, jako zip, po pominięciu plików pasujących do typowych danych poufnych.','Open Babilim settings'=>'Otwórz ustawienia Babilim','Original language'=>'Język oryginalny','Original string'=>'Oryginalny ciąg znaków','Paid'=>'Płatny','Partner'=>'Partner','Please check that your site can be reached from the internet, then try again.'=>'Sprawdź, czy Twoja witryna jest dostępna z internetu, a następnie spróbuj ponownie.','Please choose a category for this report.'=>'Wybierz kategorię dla tego zgłoszenia.','Plugin'=>'Wtyczka','Plugin · %s'=>'Wtyczka · %s','Plugins'=>'Wtyczki','Preview'=>'Podgląd','Purchase restored. This site is now licensed.'=>'Zakup został przywrócony. Ta witryna ma teraz licencję.','Re-parsed entry count did not match the built index.'=>'Liczba wpisów po ponownej analizie nie zgadza się z zbudowanym indeksem.','Re-verify'=>'Zweryfikuj ponownie','Rebuild index now'=>'Odbuduj indeks teraz','Refusing to write outside the Babilim language-file directory.'=>'Odmowa zapisu poza katalogiem plików językowych Babilim.','Registration response was missing required fields.'=>'W odpowiedzi rejestracji brakowało wymaganych pól.','Registration restarted.'=>'Rejestracja została uruchomiona ponownie.','Remove'=>'Usuń','Remove everything Babilim installed'=>'Usuń wszystko, co zainstalował Babilim','Remove everything Babilim installed? This deletes every language file it installed for every plugin and theme on this site.'=>'Usunąć wszystko, co zainstalował Babilim? Spowoduje to usunięcie wszystkich plików językowych zainstalowanych przez Babilim dla każdej wtyczki i motywu w tej witrynie.','Remove the %2$s translation of %1$s from this site?'=>'Usunąć tłumaczenie %2$s dla %1$s z tej witryny?','Removed %d installed component.'=>'Usunięto %d zainstalowany komponent.' . "\0" . 'Usunięto %d zainstalowane komponenty.' . "\0" . 'Usunięto %d zainstalowanych komponentów.','Removed after a failed integrity check'=>'Usunięto po nieudanej kontroli integralności','Removed.'=>'Usunięto.','Removes every language file Babilim has installed for every plugin and theme on this site.'=>'Usuwa wszystkie pliki językowe zainstalowane przez Babilim dla każdej wtyczki i motywu w tej witrynie.','Report a problem'=>'Zgłoś problem','Report translation'=>'Zgłoś tłumaczenie','Request newer translation'=>'Zamów nowsze tłumaczenie','Request translation'=>'Zamów tłumaczenie','Requestable'=>'Można zgłosić prośbę','Requesting a translation puts this plugin or theme on one of the free service plan\'s slots for this site (the limit is %1$d for themes and %2$d for plugins), unless it already has one. A slot stays used, and a failed translation does not free it.'=>'Zlecenie tłumaczenia powoduje przypisanie tej wtyczki lub tego motywu do jednego z miejsc bezpłatnego planu usługi dla tej witryny (limit wynosi %1$d dla motywów i %2$d dla wtyczek), chyba że już je ma. Miejsce pozostaje zajęte, a nieudane tłumaczenie go nie zwalnia.','Requesting a translation puts this plugin or theme on one of the free service plan\'s slots for this site, unless it already has one. A slot stays used, and a failed translation does not free it.'=>'Zlecenie tłumaczenia powoduje przypisanie tej wtyczki lub tego motywu do jednego z miejsc bezpłatnego planu usługi dla tej witryny, chyba że już je ma. Miejsce pozostaje zajęte, a nieudane tłumaczenie go nie zwalnia.','Requesting…'=>'Zamawianie…','Restart registration'=>'Uruchom rejestrację ponownie','Restore code'=>'Kod przywracania','Restore purchase'=>'Przywróć zakup','Retry request'=>'Ponów żądanie','Roll back'=>'Przywróć poprzednią wersję','Roll back and report'=>'Przywróć poprzednią wersję i zgłoś','Roll back and send report'=>'Przywróć poprzednią wersję i wyślij zgłoszenie','Roll back the %2$s translation of %1$s to the previous build?'=>'Przywrócić poprzednią kompilację tłumaczenia %2$s dla %1$s?','Rolled back and reported.'=>'Przywrócono i zgłoszono.','Rolled back to the previous build.'=>'Przywrócono poprzednią wersję.','Rolled back, but the report could not be sent: %s'=>'Przywrócono, ale nie udało się wysłać zgłoszenia: %s','Rolling back would overwrite \'%1$s\' (%2$s), which is now served for another installed component (%3$s); nothing was changed.'=>'Przywrócenie poprzedniej wersji nadpisałoby „%1$s” (%2$s), który jest teraz udostępniany dla innego zainstalowanego komponentu (%3$s); nic nie zostało zmienione.','Rotate-token response was missing site_token.'=>'W odpowiedzi na zmianę tokenu brakowało site_token.','Save changes'=>'Zapisz zmiany','Scheduled, waiting to be processed'=>'Zaplanowano, oczekuje na przetworzenie','Search'=>'Szukaj','Search components'=>'Szukaj komponentów','Search the installed translations'=>'Przeszukaj zainstalowane tłumaczenia','Select all'=>'Zaznacz wszystko','Select fewer components: at most %1$d operations per run (you selected %2$d).'=>'Wybierz mniej składników: maksymalnie %1$d operacji na jedno uruchomienie (wybrano: %2$d).','Send report'=>'Wyślij raport','Service plan'=>'Plan usługi','Settings'=>'Ustawienia','Share error reports'=>'Udostępniaj raporty o błędach','Share this report'=>'Udostępnij ten raport','Show a new restore code'=>'Pokaż nowy kod przywracania','Show the "Report translation" entry in the admin toolbar'=>'Pokaż pozycję „Zgłoś tłumaczenie” na pasku narzędzi administratora','Some of this component\'s text is hard-coded by its author and can\'t be translated by a language pack.'=>'Część tekstu tego komponentu jest na stałe zapisana w kodzie przez jego autora i nie może zostać przetłumaczona przez pakiet językowy.','Status'=>'Status','Status unknown'=>'Status nieznany','String context'=>'Kontekst ciągu','Suggested translation'=>'Sugerowane tłumaczenie','Supplementary translation index'=>'Uzupełniający indeks tłumaczeń','Supplementary translation index rebuilt.'=>'Uzupełniający indeks tłumaczeń został odbudowany.','Supplementary translation maintenance'=>'Konserwacja uzupełniającego indeksu tłumaczeń','Supplementary translations'=>'Tłumaczenia uzupełniające','Sweep aborted without orphaning anything: %s.'=>'Czyszczenie przerwano bez osieracania czegokolwiek: %s.','Sweep complete: %d file deleted.'=>'Czyszczenie zakończone: usunięto %d plik.' . "\0" . 'Czyszczenie zakończone: usunięto %d pliki.' . "\0" . 'Czyszczenie zakończone: usunięto %d plików.','Sweep now'=>'Wyczyść teraz','Sync complete.'=>'Synchronizacja zakończona.','Thank you. Your report was sent.'=>'Dziękujemy. Twoje zgłoszenie zostało wysłane.','That component is not installed on this site, so a translation cannot be requested for it.'=>'Ten komponent nie jest zainstalowany w tej witrynie, więc nie można zażądać dla niego tłumaczenia.','That does not look like a restore code.'=>'To nie wygląda na kod przywracania.','That is not a valid WordPress locale code. Nothing was saved.'=>'To nie jest prawidłowy kod locale WordPress. Nic nie zostało zapisane.','That is not a valid build identifier.'=>'To nie jest prawidłowy identyfikator kompilacji.','That upload screen was out of date: a different upload has been prepared since. Nothing was sent. Review the current one from the Translations list.'=>'Ten ekran przesyłania był nieaktualny: od tego czasu przygotowano inne przesłanie. Nic nie zostało wysłane. Sprawdź aktualne na Liście tłumaczeń.','The change could not be recorded in the translation index; please try again.'=>'Nie udało się zapisać zmiany w indeksie tłumaczeń. Spróbuj ponownie.','The cleanup ran, but some of its changes could not be recorded in the translation index; the next cleanup will retry them.'=>'Czyszczenie zostało wykonane, ale niektórych jego zmian nie udało się zapisać w indeksie tłumaczeń; następne czyszczenie ponowi próbę.','The component has no files that can be uploaded.'=>'Komponent nie zawiera plików, które można przesłać.','The component is not inside the plugins or themes directory.'=>'Komponent nie znajduje się w katalogu wtyczek ani motywów.','The component\'s main file was not found.'=>'Nie znaleziono głównego pliku komponentu.','The download response was missing a usable location.'=>'W odpowiedzi pobierania brakowało użytecznej lokalizacji.','The entry opens a panel to search the translations Babilim installed on this site and report one of them.'=>'Ta pozycja otwiera panel do wyszukiwania tłumaczeń zainstalowanych przez Babilim w tej witrynie i zgłaszania jednego z nich.','The field "%1$s" is too long: it has %2$d characters and the limit is %3$d. Nothing was sent; please shorten it and try again.'=>'Pole „%1$s” jest za długie: ma %2$d znaków, a limit wynosi %3$d. Nic nie zostało wysłane; skróć je i spróbuj ponownie.','The free service plan gives each site a limited number of slots for plugins and themes; the slots in use are shown in Settings after you enable Babilim.'=>'Bezpłatny plan usługi daje każdej witrynie ograniczoną liczbę miejsc dla wtyczek i motywów; wykorzystane miejsca są widoczne w Ustawieniach po włączeniu Babilim.','The given domain \'%1$s\' matches neither the package manifest\'s own slug \'%2$s\' nor its text_domain \'%3$s\'.'=>'Podana domena „%1$s” nie odpowiada ani własnemu slugowi manifestu pakietu „%2$s”, ani jego text_domain „%3$s”.','The merged index for \'%s\' was rebuilt, but the translation index could not record it; the next rebuild will retry.'=>'Scalony indeks dla \'%s\' został odbudowany, ale indeks tłumaczeń nie mógł go zapisać; następna odbudowa ponowi próbę.','The original text and the translations made from it will be provided to other sites that install the same version.'=>'Tekst oryginalny i powstałe na jego podstawie tłumaczenia zostaną udostępnione innym witrynom, które instalują tę samą wersję.','The package declares no main translation file.'=>'Pakiet nie deklaruje głównego pliku tłumaczenia.','The package has no %s for its own text domain.'=>'Pakiet nie zawiera pliku %s dla własnego text domain.','The package manifest\'s kind \'%1$s\' does not match the requested kind \'%2$s\'.'=>'Rodzaj „%1$s” w manifeście pakietu nie odpowiada żądanemu rodzajowi „%2$s”.','The package produced no servable main translation file.'=>'Pakiet nie wytworzył żadnego możliwego do udostępnienia głównego pliku tłumaczenia.','The package\'s text domain \'%1$s\' does not match this site\'s copy of the component (\'%2$s\'), so it was not installed.'=>'Text domain pakietu („%1$s”) nie odpowiada text domain kopii komponentu w tej witrynie („%2$s”), dlatego pakiet nie został zainstalowany.','The packaged component could not be read.'=>'Nie można odczytać spakowanego komponentu.','The registration challenge is not in the expected form.'=>'Wyzwanie rejestracji nie ma oczekiwanej postaci.','The report could not be sent.'=>'Nie udało się wysłać raportu.','The search could not be completed.'=>'Nie udało się zakończyć wyszukiwania.','The service asked this site to wait before syncing again.'=>'Usługa poprosiła tę witrynę o odczekanie przed kolejną synchronizacją.','The service could not reach your site. A firewall, security plugin or host rule is probably blocking the request; please allow requests to /wp-json/babilim/v1/challenge.'=>'Usługa nie mogła połączyć się z Twoją witryną. Prawdopodobnie zapora sieciowa, wtyczka zabezpieczeń lub reguła hostingu blokuje żądanie; zezwól na żądania do /wp-json/babilim/v1/challenge.','The service\'s upload offer was incomplete.'=>'Oferta przesyłania z usługi była niekompletna.','The text domain \'%1$s\' (%2$s) is already served for another installed component (%3$s); nothing was installed.'=>'Text domain „%1$s” (%2$s) jest już udostępniany dla innego zainstalowanego komponentu (%3$s); nic nie zostało zainstalowane.','The upload is kept until you ask Babilim to delete it.'=>'Przesłane pliki są przechowywane, dopóki nie poprosisz Babilim o ich usunięcie.','Theme'=>'Motyw','Theme · %s'=>'Motyw · %s','Themes'=>'Motywy','There is no upload in progress.'=>'Nie trwa żadne przesyłanie.','There is no upload waiting for confirmation.'=>'Nie ma przesyłania oczekującego na potwierdzenie.','These are the languages this site uses. You can change them in %s.'=>'Oto języki używane na tej witrynie. Możesz je zmienić w %s.','These fields will be sent:'=>'Te pola zostaną wysłane:','This build is not one this site currently knows about for this component/locale.'=>'Ta wersja nie jest obecnie znana tej witrynie dla tego komponentu i locale.','This component does not declare a version number, so a translation cannot be requested for it.'=>'Ten komponent nie deklaruje numeru wersji, więc nie można zażądać dla niego tłumaczenia.','This component is larger than the service accepts, so it cannot be uploaded.'=>'Ten komponent jest większy, niż akceptuje usługa, więc nie można go przesłać.','This component was already uploaded. Babilim is checking it now.'=>'Ten komponent został już przesłany. Babilim sprawdza go teraz.','This component\'s version number is longer than %d characters, which Babilim cannot handle, so a translation cannot be requested for it.'=>'Numer wersji tego komponentu jest dłuższy niż %d znaków, czego Babilim nie obsługuje, więc nie można zażądać dla niego tłumaczenia.','This issues a new restore code and the previous one stops working. Continue?'=>'Spowoduje to wydanie nowego kodu przywracania, a poprzedni przestanie działać. Kontynuować?','This network has too many sites to check them one by one, and some of them may be set to erase their Babilim identity when the plugin is deleted. The paid license attached to such a site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identities, press Cancel, untick "Delete all Babilim data on uninstall" in each site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'Ta sieć ma zbyt wiele witryn, aby sprawdzać je pojedynczo, a niektóre z nich mogą być ustawione tak, aby usunąć tożsamość Babilim po usunięciu wtyczki. Licencja płatna przypisana do takiej witryny nie mogłaby wtedy zostać przywrócona automatycznie; musiałbyś skontaktować się ze wsparciem Babilim pod adresem %s. Aby zachować tożsamości, naciśnij Anuluj, odznacz „Usuń wszystkie dane Babilim podczas odinstalowania” w ustawieniach Babilim każdej witryny i ponownie dezaktywuj. Dezaktywować mimo to?','This plugin\'s own version, so the service can tell you to update it if it\'s too old to talk to.'=>'Wersja samej tej wtyczki, aby usługa mogła poinformować Cię o konieczności jej aktualizacji, jeśli jest zbyt stara, by się z nią komunikować.','This report does not name a valid plugin or theme and locale.'=>'To zgłoszenie nie wskazuje prawidłowej wtyczki ani motywu oraz locale.','This report does not name an installed string.'=>'To zgłoszenie nie wskazuje żadnego zainstalowanego ciągu znaków.','This report is missing a valid build to report against.'=>'W tym zgłoszeniu brakuje prawidłowej wersji, której ma dotyczyć.','This report will be posted publicly on GitHub and may be kept by third parties.'=>'Ten raport zostanie publicznie opublikowany na GitHub i może być przechowywany przez osoby trzecie.','This restore code was not recognised for this site.'=>'Ten kod przywracania nie został rozpoznany dla tej witryny.','This site already has an active registration that can no longer be recovered automatically.'=>'Ta witryna ma już aktywną rejestrację, której nie można już automatycznie odzyskać.','This site has %1$d components across %2$d languages, which needs %3$d check batches; Babilim can handle at most %4$d per run. Reduce the managed languages in Settings or deactivate unused plugins and themes, then press Check again now.'=>'Liczba komponentów w tej witrynie: %1$d; liczba języków: %2$d. Wymagana liczba partii sprawdzania: %3$d. Babilim może obsłużyć najwyżej %4$d partii na jedno uruchomienie. Zmniejsz liczbę zarządzanych języków w Ustawieniach lub dezaktywuj nieużywane wtyczki i motywy, a następnie kliknij Sprawdź ponownie teraz.','This site has no purchase to show a code for.'=>'Ta witryna nie ma zakupu, dla którego można pokazać kod.','This site is already licensed. Reload the page.'=>'Ta witryna ma już licencję. Odśwież stronę.','This site is not registered with Babilim yet.'=>'Ta witryna nie jest jeszcze zarejestrowana w Babilim.','This site is over the size the service accepts in one sync, so some items were left out: %1$d components and %2$d locales.'=>'Ta witryna przekracza rozmiar akceptowany przez usługę w jednej synchronizacji, więc niektóre elementy pominięto: komponenty: %1$d, ustawienia regionalne: %2$d.','This site is part of a multisite network, which does not install new translations automatically. Translations that are already installed are still updated.'=>'Ta witryna jest częścią sieci multisite, która nie instaluje nowych tłumaczeń automatycznie. Już zainstalowane tłumaczenia są nadal aktualizowane.','This site is verified.'=>'Ta witryna została zweryfikowana.','This site must be verified first.'=>'Ta witryna musi najpierw zostać zweryfikowana.','This site\'s URL, so the service can verify you own it.'=>'Adres URL tej witryny, aby usługa mogła zweryfikować, że jesteś jej właścicielem.','This site\'s address is too long for Babilim to register.'=>'Adres tej witryny jest zbyt długi, aby Babilim mógł ją zarejestrować.','This site\'s configured locale.'=>'Skonfigurowany locale tej witryny.','This site\'s locale code is not one Babilim can register.'=>'Babilim nie może zarejestrować kodu locale tej witryny.','This string can\'t be reported from this site.'=>'Tego ciągu nie można zgłosić z tej witryny.','This string is not among the translations installed on this site. Search again and pick it from the list.'=>'Ten ciąg znaków nie należy do tłumaczeń zainstalowanych w tej witrynie. Wyszukaj ponownie i wybierz go z listy.','This translation was updated since you searched. Search again and pick the string from the new list.'=>'To tłumaczenie zostało zaktualizowane po wyszukaniu. Wyszukaj ponownie i wybierz ciąg znaków z nowej listy.','To translate this component, Babilim needs its source.'=>'Aby przetłumaczyć ten komponent, Babilim potrzebuje jego kodu źródłowego.','Too many attempts. Try again tomorrow.'=>'Zbyt wiele prób. Spróbuj ponownie jutro.','Too many reports today. Try again tomorrow.'=>'Zbyt wiele zgłoszeń dzisiaj. Spróbuj ponownie jutro.','Too many requests.'=>'Zbyt wiele żądań.','Toolbar'=>'Pasek narzędzi','Translating…'=>'Tłumaczenie…','Translation does not load'=>'Tłumaczenie się nie ładuje','Translation failed'=>'Tłumaczenie nie powiodło się','Translation files you put in %s always take priority over Babilim\'s. They are kept unless you uncheck this.'=>'Pliki tłumaczeń umieszczone w %s zawsze mają pierwszeństwo przed plikami Babilim. Są zachowywane, chyba że odznaczysz tę opcję.','Translation requested.'=>'Zażądano tłumaczenia.','Translations'=>'Tłumaczenia','Type'=>'Typ','Type at least 2 characters to search.'=>'Wpisz co najmniej 2 znaki, aby wyszukać.','Unexpected HTTP %d response.'=>'Nieoczekiwana odpowiedź HTTP %d.','Uninstall'=>'Odinstalowanie','Unknown kind: %s'=>'Nieznany rodzaj: %s','Unsafe domain: %s'=>'Niebezpieczna domena: %s','Unsafe locale: %s'=>'Niebezpieczny locale: %s','Unsafe slug: %s'=>'Niebezpieczny slug: %s','Unsafe text_domain: %s'=>'Niebezpieczny text_domain: %s','Update'=>'Aktualizuj','Update available'=>'Dostępna aktualizacja','Updates'=>'Aktualizacje','Updating…'=>'Aktualizowanie…','Upgrade this site'=>'Ulepsz tę witrynę','Upload and request'=>'Prześlij i poproś o tłumaczenie','Upload cancelled.'=>'Anulowano przesyłanie.','Upload complete — translation requested.'=>'Przesyłanie zakończone — zażądano tłumaczenia.','Upload expired before it finished'=>'Przesyłanie wygasło przed zakończeniem','Upload in progress — continue or cancel'=>'Przesyłanie w toku — kontynuuj lub anuluj','Upload this component?'=>'Przesłać ten komponent?','Upload was not accepted'=>'Przesyłanie nie zostało zaakceptowane','Uploading'=>'Przesyłanie','Uploading part %1$d of %2$d…'=>'Przesyłanie części %1$d z %2$d…','Uploading…'=>'Przesyłanie…','Verified'=>'Zweryfikowano','Verify response was missing site_token.'=>'W odpowiedzi weryfikacji brakowało site_token.','Version %s'=>'Wersja %s','What is sent when you enable Babilim'=>'Co jest wysyłane po włączeniu Babilim','When something fails inside Babilim, send an error report to the Babilim service so it can be published as a public issue on GitHub. The report is sent as coming from this site, with the same authentication as every other request to the Babilim service. The service publishes only the error code and versions as a public issue on GitHub; the public issue contains no site address, content or file paths. Off by default.'=>'Gdy w Babilim coś zawiedzie, wyślij raport o błędzie do usługi Babilim, aby mógł zostać opublikowany jako publiczne zgłoszenie na GitHub. Raport jest wysyłany jako pochodzący z tej witryny, z tym samym uwierzytelnianiem co każde inne żądanie do usługi Babilim. Usługa publikuje jako publiczne zgłoszenie na GitHub wyłącznie kod błędu i wersje; publiczne zgłoszenie nie zawiera adresu witryny, treści ani ścieżek plików. Domyślnie wyłączone.','Where you saw this (optional)'=>'Gdzie to zobaczono (opcjonalnie)','While this is on, translations the service lists as available for the languages you manage are installed during the twice-daily sync.'=>'Gdy ta opcja jest włączona, tłumaczenia, które usługa wskazuje jako dostępne dla zarządzanych przez Ciebie języków, są instalowane podczas synchronizacji dwa razy dziennie.','WordPress.org'=>'WordPress.org','Wrong for this context'=>'Błędne w tym kontekście','Wrong meaning'=>'Błędne znaczenie','Wrong plural form'=>'Nieprawidłowa forma liczby mnogiej','Wrong term'=>'Błędny termin','Yes'=>'Tak','You are not allowed to do this.'=>'Nie masz uprawnień do wykonania tej czynności.','Your PHP version, for compatibility.'=>'Wersja Twojego PHP, ze względu na zgodność.','Your WordPress version, to serve compatible translation files.'=>'Wersja Twojego WordPressa, aby udostępniać zgodne pliki tłumaczeń.','Your new restore code: %s. Keep it somewhere safe — the previous code no longer works.'=>'Twój nowy kod przywracania: %s. Zachowaj go w bezpiecznym miejscu — poprzedni kod już nie działa.','Your report is processed automatically by AI models and may improve this translation for other sites.'=>'Twoje zgłoszenie jest przetwarzane automatycznie przez modele AI i może poprawić to tłumaczenie w innych witrynach.','Your site answered, but not with what was expected. The REST API may be rewritten by another plugin, or that endpoint may be cached; please exclude /wp-json/babilim/v1/challenge from caching and rewriting.'=>'Twoja witryna odpowiedziała, ale nie tak, jak oczekiwano. REST API może być przepisywane przez inną wtyczkę lub ten punkt końcowy może być buforowany; wyklucz /wp-json/babilim/v1/challenge z buforowania i przepisywania.','Your site took too long to answer. Please try again later, and check that your host is not too slow or overloaded.'=>'Twoja witryna odpowiedziała zbyt wolno. Spróbuj ponownie później i sprawdź, czy hosting nie jest zbyt wolny lub przeciążony.','Zip has no manifest.json.'=>'Archiwum zip nie zawiera pliku manifest.json.','Zip is missing expected default file: %s'=>'W archiwum zip brakuje oczekiwanego pliku domyślnego: %s','Zip is missing expected file: %s'=>'W archiwum zip brakuje oczekiwanego pliku: %s','_manifest.json has an unexpected structure'=>'Plik _manifest.json ma nieoczekiwaną strukturę','could not read _manifest.json: %s'=>'nie udało się odczytać pliku _manifest.json: %s','expected_manifest is missing or has an invalid \'%s\'.'=>'Brakuje expected_manifest lub ma on nieprawidłowe pole „%s”.','expected_manifest\'s \'server_build_id\' is not a valid build id.'=>'Pole „server_build_id” w expected_manifest nie jest prawidłowym identyfikatorem kompilacji.','failed to parse _manifest.json: %s'=>'Nie udało się przeanalizować pliku _manifest.json: %s','it would orphan %1$d of %2$d managed components (more than half)'=>'osierociłoby to %1$d z %2$d zarządzanych komponentów (więcej niż połowę)','it would orphan every managed %1$s component (%2$d of %2$d)'=>'osierociłoby to wszystkie zarządzane komponenty (%1$s: %2$d z %2$d)','l10n.php entry count mismatch for %s'=>'Niezgodna liczba wpisów l10n.php dla %s','manifest.json has an invalid \'default_domain_entries\'.'=>'manifest.json zawiera nieprawidłowe pole „default_domain_entries”.','manifest.json has an invalid \'default_domain_files\'.'=>'manifest.json zawiera nieprawidłowe pole „default_domain_files”.','manifest.json in the zip is not valid JSON.'=>'manifest.json w archiwum zip nie jest prawidłowym plikiem JSON.','manifest.json is missing or has an invalid \'%s\'.'=>'W manifest.json brakuje pola „%s” lub jest ono nieprawidłowe.','manifest.json is missing or has an invalid \'build_no\'.'=>'W manifest.json brakuje pola „build_no” lub jest ono nieprawidłowe.','manifest.json is missing or has an invalid \'entries\'.'=>'W manifest.json brakuje pola „entries” lub jest ono nieprawidłowe.','manifest.json is missing or has an invalid \'extra_domains\'.'=>'W manifest.json brakuje pola „extra_domains” lub jest ono nieprawidłowe.','manifest.json is missing or has an invalid \'files\'.'=>'W manifest.json brakuje pola „files” lub jest ono nieprawidłowe.','manifest.json\'s \'%s\' does not match the expected value.'=>'Pole „%s” w manifest.json nie odpowiada oczekiwanej wartości.','manifest.json\'s \'contract\' is not a valid version string.'=>'Pole „contract” w manifest.json nie jest prawidłowym ciągiem wersji.','manifest.json\'s \'kind\' must be \'plugin\' or \'theme\'.'=>'Pole „kind” w manifest.json musi mieć wartość „plugin” lub „theme”.','manifest.json\'s \'server_build_id\' is not a valid build id.'=>'Pole „server_build_id” w manifest.json nie jest prawidłowym identyfikatorem kompilacji.','manifest.json\'s \'status\' must be \'published\'.'=>'Pole „status” w manifest.json musi mieć wartość „published”.','nonce must be a hexadecimal string.'=>'nonce musi być ciągiem szesnastkowym.','per day'=>'dziennie','rc_…'=>'rc_…','sha256 mismatch for %s'=>'Niezgodność sha256 dla %s','sha256 mismatch for default/%s'=>'Niezgodność sha256 dla default/%s','component kind in the sweep brake messageplugin'=>'wtyczka','component kind in the sweep brake messagetheme'=>'motyw','problem report categoryOther'=>'Inne','translation statusAvailable'=>'Dostępne','translation statusInstalled'=>'Zainstalowano','Babilim translation turned off.'=>'Tłumaczenie Babilim zostało wyłączone.','Stop using Babilim translation'=>'Przestań używać tłumaczenia Babilim','Use Babilim translation'=>'Użyj tłumaczenia Babilim','Stop using the Babilim translation of %1$s (%2$s)? WordPress will use the theme\'s own or WordPress.org translation instead. You can switch back at any time.'=>'Przestać używać tłumaczenia Babilim dla motywu %1$s (%2$s)? WordPress użyje zamiast tego własnego tłumaczenia motywu lub tłumaczenia WordPress.org. W każdej chwili możesz wrócić do poprzedniego ustawienia.','Stop using the Babilim translation of %1$s (%2$s)? WordPress will use the plugin\'s own or WordPress.org translation instead. You can switch back at any time.'=>'Przestać używać tłumaczenia Babilim dla wtyczki %1$s (%2$s)? WordPress użyje zamiast tego własnego tłumaczenia wtyczki lub tłumaczenia WordPress.org. W każdej chwili możesz wrócić do poprzedniego ustawienia.']];